const updateOrganizationTeam = `-- name: UpdateOrganizationTeam :one
WITH RECURSIVE descendants(descendant_id) AS (
  SELECT child.id
  FROM core.organization_teams AS child
  WHERE child.parent_team_id = $6 AND child.deleted_at IS NULL
  UNION ALL
  SELECT child.id
  FROM core.organization_teams AS child
  JOIN descendants AS parent ON child.parent_team_id = parent.descendant_id
  WHERE child.deleted_at IS NULL
)
UPDATE core.organization_teams AS team
SET parent_team_id = $1,
    name = $2,
    description = $3,
    visibility = $4,
    updated_at = $5
WHERE team.id = $6
  AND team.organization_id = $7
  AND team.deleted_at IS NULL
  AND (
    $1::uuid IS NULL
    OR (
      $4::text = 'visible'
      AND $1::uuid <> $6
      AND NOT EXISTS (SELECT 1 FROM descendants WHERE descendants.descendant_id = $1::uuid)
      AND EXISTS (
        SELECT 1 FROM core.organization_teams AS parent
        WHERE parent.id = $1::uuid
          AND parent.organization_id = $7
          AND parent.visibility = 'visible'
          AND parent.deleted_at IS NULL
      )
    )
  )
  AND (
    $4::text <> 'secret'
    OR (
      $1::uuid IS NULL
      AND NOT EXISTS (SELECT 1 FROM descendants)
    )
  )
RETURNING team.id, team.organization_id, team.parent_team_id, team.slug, team.name, team.description, team.visibility, team.created_at, team.updated_at, team.deleted_at
`

type UpdateOrganizationTeamParams struct {
	ParentTeamID   pgtype.UUID        `json:"parent_team_id"`
	Name           string             `json:"name"`
	Description    pgtype.Text        `json:"description"`
	Visibility     string             `json:"visibility"`
	UpdatedAt      pgtype.Timestamptz `json:"updated_at"`
	ID             pgtype.UUID        `json:"id"`
	OrganizationID pgtype.UUID        `json:"organization_id"`
}

func (q *Queries) UpdateOrganizationTeam(ctx context.Context, arg UpdateOrganizationTeamParams) (CoreOrganizationTeam, error) {
	row := q.db.QueryRow(ctx, updateOrganizationTeam,
		arg.ParentTeamID,
		arg.Name,
		arg.Description,
		arg.Visibility,
		arg.UpdatedAt,
		arg.ID,
		arg.OrganizationID,
	)
	var i CoreOrganizationTeam
	err := row.Scan(
		&i.ID,
		&i.OrganizationID,
		&i.ParentTeamID,
		&i.Slug,
		&i.Name,
		&i.Description,
		&i.Visibility,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
	)
	return i, err
}
